'BEGIN',
'    l_inicio       := systimestamp;',
'    apex_web_service.g_request_headers.delete;',
'    apex_web_service.g_request_headers(1).name :=',
'        ''Content-Type'';',
'    apex_web_service.g_request_headers(1).value :=',
'        ''application/json'';',
'    l_response :=',
'        apex_web_service.make_rest_request(',
'            p_url         => ''https://tributai.duckdns.org/embed'',',
'            p_http_method => ''POST'',',
'            p_body        => ''{"pergunta":"'' || replace(:P2_PERGUNTA,''"'',''\"'') || ''"}''  );',
'    :P2_EMBEDDING_JSON := json_query(  l_response,  ''$.embedding''  RETURNING CLOB );',
'    SELECT id_chunk',
'      INTO l_id_chunk_top1',
'      FROM (',
'            SELECT id_chunk,',
'                   vector_distance(',
'                       embedding,',
'                       to_vector(:P2_EMBEDDING_JSON),',
'                       cosine',
'                   ) distancia',
'              FROM tributai.tai_chunk_t',
'             ORDER BY distancia',
'           )',
'     WHERE ROWNUM = 1;',
'',
'    --l_tempo_ms := EXTRACT(DAY FROM (SYSTIMESTAMP - l_inicio)) * 86400000 +',
'    --              EXTRACT(HOUR FROM (SYSTIMESTAMP - l_inicio)) * 3600000 +',
'    --              EXTRACT(MINUTE FROM (SYSTIMESTAMP - l_inicio)) * 60000 +',
'    --              EXTRACT(SECOND FROM (SYSTIMESTAMP - l_inicio)) * 1000;',
'    l_tempo_ms := ROUND( EXTRACT(SECOND FROM (SYSTIMESTAMP - l_inicio)) * 1000 );',
'',
'',
'    INSERT INTO  tributai.tai_hist_pergunta_t ( DT_CONSULTA',
'                                               , PERGUNTA',
'                                               , IP_USUARIO',
'                                               , USER_AGENT',
'                                               , TEMPO_MS',
'                                               , QTD_RESULTADOS',
'                                               , ID_CHUNK_TOP1',
'                                               , STATUS_CONSULTA                                               ',
'                                               )',
'                                        VALUES ( SYSTIMESTAMP',
'                                               , :P2_PERGUNTA',
'                                               , owa_util.get_cgi_env(''REMOTE_ADDR'') --sys_context(''userenv'',''ip_address'')',
'                                               , owa_util.get_cgi_env(''HTTP_USER_AGENT'')',
'                                               , l_tempo_ms',
'                                               , NULL',
'                                               , l_id_chunk_top1',
'                                               , ''SUCESSO''',
'                                               );',
'',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(10088699705872503)
,p_process_when=>'P2_PERGUNTA'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>10089134240872508
);
end;
